WITH total_assignment_time AS (SELECT SUM(subq_1.total_assignment_time_measure) AS total_assignment_time, subq_1.day AS day, dim_agent.agent_type AS agent_type, dim_agent.agent_team AS agent_team FROM (SELECT timeDiff(fact_ticket_journey.raised_at, fact_ticket_journey.accepted_at) / (60.0) AS total_assignment_time_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, final_agent_id AS agent FROM fact_ticket_journey WHERE 1 = 1) AS subq_1 JOIN dim_agent AS dim_agent ON subq_1.agent = dim_agent.agent_id GROUP BY day, agent_team, agent_type), total_tickets_raised AS (SELECT subq_3.day AS day, COUNT(subq_3.total_tickets_raised_measure) AS total_tickets_raised, dim_agent.agent_type AS agent_type, dim_agent.agent_team AS agent_team FROM (SELECT fact_ticket_journey.ticket_id AS total_tickets_raised_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, final_agent_id AS agent FROM fact_ticket_journey WHERE 1 = 1) AS subq_3 JOIN dim_agent AS dim_agent ON subq_3.agent = dim_agent.agent_id GROUP BY day, agent_team, agent_type), prefinal_cte AS (SELECT total_assignment_time.agent_team AS agent_team, total_assignment_time.day AS day, total_assignment_time.agent_type AS agent_type, MAX(total_assignment_time.total_assignment_time) AS total_assignment_time, MAX(total_tickets_raised.total_tickets_raised) AS total_tickets_raised FROM total_assignment_time JOIN total_tickets_raised AS total_tickets_raised ON total_assignment_time.agent_team = total_tickets_raised.agent_team AND total_assignment_time.day = total_tickets_raised.day AND total_assignment_time.agent_type = total_tickets_raised.agent_type GROUP BY agent_team, day, agent_type) SELECT day AS day, agent_team AS agent_team, agent_type AS agent_type, MAX(total_assignment_time / total_tickets_raised) AS avg_assignment_time FROM prefinal_cte GROUP BY day, agent_team, agent_type